SELECT *
FROM table_bd4f8d5ffa8239c09831e5b997bc2753
LIMIT 5;

SELECT "Religion", COUNT(*) as PatientCount
FROM table_bd4f8d5ffa8239c09831e5b997bc2753
GROUP BY "Religion";

SELECT Religion, COUNT(*) AS PatientCount
FROM table_c83679f393c19ab82f71054c6c3facb6
GROUP BY Religion;

SELECT "Locum/Residence", AVG("TotalRevenue") AS average_revenue
FROM table_c83679f393c19ab82f71054c6c3facb6
GROUP BY "Locum/Residence";
